async (slug, data = {}, options = {}) => {
    helperDebugLog("execute.prepare", {
      slug,
      hasData: data !== undefined,
      account: options.account ?? null
    });
    const args2 = ["execute", slug];
    if (helperContext.dryRun === true)
      args2.push("--dry-run");
    if (helperContext.skipConnectionCheck === true)
      args2.push("--skip-connection-check");
    if (helperContext.skipToolParamsCheck === true)
      args2.push("--skip-tool-params-check");
    if (helperContext.skipChecks === true)
      args2.push("--skip-checks");
    if (typeof options.account === "string" && options.account.trim().length > 0) {
      args2.push("--account", options.account.trim());
    }
    if (data !== undefined) {
      const preparedData = await materializeExecutePayload(data);
      const serialized = typeof preparedData === "string" ? preparedData : JSON.stringify(preparedData);
      if (sharedRunOutputDir) {
        const tmpFile = `${sharedRunOutputDir}/execute-data-${slug}-${executeId()}.json`;
        fs4.writeFileSync(tmpFile, serialized, "utf8");
        args2.push("--data", `@${tmpFile}`);
      } else {
        args2.push("--data", serialized);
      }
    }
    const result = await runCliJson(args2);
    if (result && typeof result === "object" && result.successful === false) {
      const message = typeof result.error === "string" && result.error.trim().length > 0 ? result.error.trim() : `composio execute ${slug} failed`;
      const error49 = new Error(message);
      Object.assign(error49, { result, slug });
      throw error49;
    }
    return result;
  }
